import{_ as t,c as a,o,a3 as r}from"./chunks/framework.BNw1pucY.js";const p=JSON.parse('{"title":"Playground","description":"The built-in web UI: chat with streaming, Try buttons and slash commands, session replay, and dev-mode dispatch.","frontmatter":{"title":"Playground","description":"The built-in web UI: chat with streaming, Try buttons and slash commands, session replay, and dev-mode dispatch."},"headers":[],"relativePath":"reference/playground.md","filePath":"reference/playground.md"}'),s={name:"reference/playground.md"};function d(n,e,l,c,i,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="playground" tabindex="-1">Playground <a class="header-anchor" href="#playground" aria-label="Permalink to &quot;Playground&quot;">​</a></h1><p><code>agent-sdk serve</code> hosts a web playground at <code>http://127.0.0.1:3000/playground</code>. When one server hosts multiple agents, each agent&#39;s playground is at <code>/&lt;slug&gt;/playground</code> and <code>/</code> lists them.</p><h2 id="playground-surfaces" tabindex="-1">Playground surfaces <a class="header-anchor" href="#playground-surfaces" aria-label="Permalink to &quot;Playground surfaces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>What you can do</th></tr></thead><tbody><tr><td>Chat</td><td>Text and reasoning stream live, and tool calls appear inline with arguments, output, and errors</td></tr><tr><td>Slash commands</td><td>Run a custom channel route without path parameters from the composer. A <code>drive</code> route becomes <code>/drive &lt;pr-url&gt;</code>. GitHub and Slack ingress routes are excluded</td></tr><tr><td>Try</td><td>Call a custom channel route from the Agent tab and copy the request as curl</td></tr><tr><td>Runs</td><td>Search the sessions you own and eval runs, then open them in Chat, Trace, Raw, or Evals</td></tr><tr><td>Evals</td><td>List and run filesystem evals</td></tr><tr><td>Agent</td><td>Inspect discovered tools, skills, subagents, MCP connections, channels, and hooks</td></tr><tr><td>Raw</td><td>Inspect the selected session&#39;s event stream</td></tr><tr><td>Logs</td><td>Recent server log lines from <code>GET /v1/logs</code></td></tr></tbody></table><p>In <code>--dev</code> on loopback, or with <code>--allow-anonymous</code>, the session list includes every principal.</p><h2 id="remote-access" tabindex="-1">Remote access <a class="header-anchor" href="#remote-access" aria-label="Permalink to &quot;Remote access&quot;">​</a></h2><p>To open the playground through a tunnel or LAN address, start the server with <code>--bearer-token &lt;secret&gt;</code> and paste the token into the navbar&#39;s token field. See <a href="./channels.html#auth-policies">Auth policies</a>.</p>',7)])])}const m=t(s,[["render",d]]);export{p as __pageData,m as default};
